def field(label,*answers):
    return {'label':label,'answers':list(answers)}

def question(id,title,prompt,fields,explain,exam='',url='',source='',visual='',self_check=False):
    return dict(id=id,title=title,prompt=prompt,fields=fields,explain=explain,
                exam=exam,url=url,source=source,visual=visual,self_check=self_check)

