def compact_preview(key):
    if key=='attacks':
        return '<div class="mini-groups"><div><b>네트워크 · 웹</b><p>DoS · DDoS<br>스니핑 · 스푸핑<br>세션 하이재킹<br>SQLi · XSS · CSRF</p></div><div><b>사회공학 · 악성코드</b><p>피싱 · 파밍 · 워터링 홀<br>바이러스 · 웜 · 트로이<br>랜섬웨어 · 루트킷<br>APT · 제로데이 · 공급망</p></div></div><p class="mini-hint">엿듣기 ≠ 위장 / 스크립트 실행 ≠ 요청 위조<br>키워드 비교와 회차별 실기 기출</p>'
    if key=='encryption':
        return '<div class="mini-groups"><div><b>대칭키 종류</b><p>블록: DES · 3DES · AES<br>SEED · ARIA · IDEA<br>Skipjack<br>스트림: RC4 · ChaCha20</p></div><div><b>비대칭키 계열</b><p>RSA · ElGamal · ECC<br>키 합의: DH · ECDH<br>서명: DSA · ECDSA</p></div></div><p class="mini-hint">DES 64/56 · AES 128/128·192·256<br>블록·키 길이와 알고리즘별 역할 비교</p>'
    if key=='version-control':
        return '<div class="mini-patterns"><p style="grid-template-columns:115px 1fr"><b>공유 폴더</b><span>RCS · SCCS</span></p><p style="grid-template-columns:115px 1fr"><b>클라이언트/서버</b><span>CVS · SVN</span></p><p style="grid-template-columns:115px 1fr"><b>분산 저장소</b><span>Git · BitKeeper</span></p></div><p class="mini-hint">폴더 공유 → 중앙 서버 → 각자 로컬 저장소<br>Git: commit은 로컬 기록 / push는 원격 전송</p>'
    if key=='routing-protocols':
        return '<div class="mini-groups"><div><b>IGP · AS 내부</b><p>거리 벡터: RIP·IGRP<br>개선형: EIGRP<br>링크 상태: OSPF·IS-IS</p></div><div><b>EGP · AS 사이</b><p>대표: BGP<br>경로 벡터 · 정책<br>eBGP / iBGP 구분</p></div></div><p class="mini-hint">RIP = 15홉 / OSPF = Dijkstra / BGP = AS 간<br>회차·출처를 확인한 RIP·OSPF 실기 기출</p>'
    if key=='drm-components':
        return '<div class="mini-level">제공자 → 패키저 → 분배자 → 소비자</div><div class="mini-chips" style="margin-top:14px"><span>보안 컨테이너<br>보호하여 담기</span><span>DRM 컨트롤러<br>이용 권한 통제</span></div><p class="mini-hint"><b>클리어링 하우스</b> · 키·라이선스·정산 관리<br>패키저 = 포장 / 분배자 = 유통</p>'
    if key=='drm-technologies':
        return '<div class="mini-chips"><span>암호화</span><span>키 관리</span><span>암호화 파일 생성</span><span>식별 기술</span><span>저작권 표현</span><span>정책 관리</span><span>크랙 방지</span><span>인증</span></div><p class="mini-hint">방화벽 · 콘텐츠 오류 감지·복구는 별도 분류</p>'
    if key=='security-cia':
        return '<div class="mini-scale"><div><b>C · 기밀성</b><span>몰래 보지 못하게</span></div><div><b>I · 무결성</b><span>함부로 바꾸지 못하게</span></div><div><b>A · 가용성</b><span>필요할 때 쓰게</span></div></div><div class="mini-level">유출 C · 변조 I · 중단 A</div><p class="mini-hint">암호화 · MAC/전자서명 · 이중화</p>'
    if key=='uml-rel':
        values=[('─','연관'),('◇─','집약'),('◆─','합성'),('─▷','일반화'),('╌╌›','의존'),('╌▷','실체화')]
        return '<div class="mini-rel">'+''.join(f'<div><span>{a}</span><b>{b}</b></div>' for a,b in values)+'</div><p class="mini-hint">◇ ◆ 전체 쪽 &nbsp; / &nbsp; ▷ 부모·명세 쪽</p>'
    if key=='uml-types':
        return '<div class="mini-groups"><div><b>구조 · 7</b><p>클래스 · 객체 · 패키지 · 컴포넌트 · 배치 · 복합 구조 · 프로파일</p></div><div><b>행위 · 7</b><p>유스케이스 · 활동 · 상태 머신<br><span>↳ 시퀀스 · 커뮤니케이션<br>상호작용 개요 · 타이밍</span></p></div></div>'
    if key=='cocomo':
        return '<div class="mini-scale"><div><b>조직형</b><span>익숙한 업무</span></div><i>→</i><div><b>반분리형</b><span>중간 성격</span></div><i>→</i><div><b>내장형</b><span>강한 제약</span></div></div><div class="mini-level">기본형 → 중간형 → 발전형</div><p class="mini-hint">규모 중심 → 비용 동인 → 단계별 보정</p>'
    if key=='patterns':
        return '<div class="mini-patterns"><p><b>생성 1</b><span>팩토리 메서드</span></p><p><b>구조 5</b><span>퍼사드 · 프록시 · 데코레이터<br>브리지 · 플라이웨이트</span></p><p><b>행위 1</b><span>옵저버</span></p></div><p class="mini-hint">선택한 7종 · 개념 그림과 회차별 실기 기출<br>생성 결정 · 단일 창구 · 대리 · 기능 추가 · 분리 · 공유 · 알림</p>'
    if key=='network':
        return '<div class="mini-level">PAN → LAN → MAN → WAN</div><div class="mini-network"><span>✳ 성형</span><span>◯ 링형</span><span>━ 버스형</span><span>⑂ 트리형</span><span>⊠ 망형</span><span>⊞ 혼합형</span></div><p class="mini-hint">유니 · 브로드 · 멀티 · 애니캐스트<br>+ 애드혹 · Infrastructure · VPN</p>'
    if key=='whitebox':
        return '<div class="mini-groups"><div><b>화이트박스</b><p>기초 경로 · 조건<br>루프 · 데이터 흐름<br>문장·분기·조건 커버리지</p></div><div><b>블랙박스</b><p>동치 분할 · 경계값<br>원인–효과 · 비교<br>결정 테이블 · 상태 전이</p></div></div><p class="mini-hint">오류 예측: 수험서에서는 함께 / ISTQB는 경험 기반<br>엣지·코너 케이스와 코드 예시 포함</p>'
    return '<div class="mini-principles">'+''.join(f'<span><i>{i+1}</i>{t}</span>' for i,t in enumerate(['결함의 존재','전수 검사 불가','조기 시작','결함 집중','살충제 패러독스','정황 의존','오류 부재의 궤변']))+'</div>'

